'use client';

import type { Value } from 'platejs';
import type { CommentThread } from 'platejs/comments';
import { CommentsPlugin } from 'platejs/comments/react';
import { Plate, useCreateEditor } from 'platejs/react';

import { BasicBlocksKit } from '@/registry/components/editor/basic-blocks';
import { createCommentValue } from '@/registry/components/editor/comment';
import { CommentToolbarButton } from '@/registry/components/editor/comment-toolbar-button';
import { DiscussionKit } from '@/registry/components/editor/discussion';
import { Editor, EditorContainer } from '@/registry/components/editor/editor';
import {
  RedoToolbarButton,
  UndoToolbarButton,
} from '@/registry/components/editor/history-toolbar-button';
import { SuggestionKit } from '@/registry/components/editor/suggestion';
import { Toolbar } from '@/registry/components/editor/toolbar';
import { commentUsers } from '@/registry/examples/values/comment-value';

export default function CommentOverlapDemo() {
  const editor = useCreateEditor({
    plugins: [
      ...BasicBlocksKit,
      ...SuggestionKit,
      ...DiscussionKit,
      CommentsPlugin.configure({
        initialState: {
          currentUserId: 'alice',
          users: commentUsers,
          initialThreads,
        },
      }),
    ],
    initialValue: value,
  });

  return (
    <Plate editor={editor}>
      <EditorContainer className="h-[360px]" variant="demo">
        <Toolbar className="border-b px-3 py-1">
          <UndoToolbarButton aria-label="Undo" />
          <RedoToolbarButton aria-label="Redo" />
          <CommentToolbarButton />
        </Toolbar>
        <Editor
          aria-label="Overlapping comments document"
          className="h-auto min-h-[280px] px-8 pb-16 sm:px-12"
          variant="demo"
        />
      </EditorContainer>
    </Plate>
  );
}

const text =
  'Edit these overlapping comments, then undo and redo your changes.';
const value: Value = [
  { type: 'paragraph', children: [{ text }] },
  {
    type: 'paragraph',
    children: [
      {
        text: 'Click “overlapping” to open both threads. Delete the first paragraph’s text and use its comment button to find the conversations again.',
      },
    ],
  },
];

const initialThreads: CommentThread[] = [
  {
    id: 'wording',
    userId: 'alice',
    createdAt: '2026-09-10T10:00:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'these overlapping',
    target: {
      type: 'range',
      range: {
        anchor: { path: [0, 0], offset: 5 },
        focus: { path: [0, 0], offset: 22 },
      },
    },
    messages: [
      {
        id: 'wording-message',
        userId: 'alice',
        createdAt: '2026-09-10T10:00:00.000Z',
        body: createCommentValue('Let’s keep this wording concise.'),
      },
    ],
  },
  {
    id: 'context',
    userId: 'bob',
    createdAt: '2026-09-10T10:01:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'overlapping comments',
    target: {
      type: 'range',
      range: {
        anchor: { path: [0, 0], offset: 11 },
        focus: { path: [0, 0], offset: 31 },
      },
    },
    messages: [
      {
        id: 'context-message',
        userId: 'bob',
        createdAt: '2026-09-10T10:01:00.000Z',
        body: createCommentValue(
          'This thread shares the word “overlapping” with Alice’s.'
        ),
      },
    ],
  },
];

import type { Value } from 'platejs';
import type { CommentThread, CommentUser } from 'platejs/comments';

import { createCommentValue } from '@/registry/components/editor/comment';

export const commentUsers: Record<string, CommentUser> = {
  alice: {
    id: 'alice',
    name: 'Alice',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=alice6',
  },
  bob: {
    id: 'bob',
    name: 'Bob',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=bob4',
  },
  charlie: {
    id: 'charlie',
    name: 'Charlie',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=charlie2',
  },
};

const trailingText =
  ' on many text segments. You can even have overlapping annotations!';

export const commentValue: Value = [
  { type: 'heading', level: 2, children: [{ text: 'Comments' }] },
  {
    type: 'paragraph',
    children: [
      { text: 'Discuss changes using ' },
      { type: 'link', url: '/docs/comment', children: [{ text: 'comments' }] },
      { text: trailingText },
    ],
  },
  {
    type: 'paragraph',
    children: [{ text: 'Select some text and add your own comment as Alice.' }],
  },
];

export const commentThreads: CommentThread[] = [
  {
    id: 'discussion1',
    createdAt: '2026-09-10T10:00:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'comments on many text segments',
    userId: 'charlie',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 1, 0], offset: 0 },
        focus: { path: [1, 2], offset: trailingText.indexOf('.') },
      },
    },
    messages: [
      {
        id: 'discussion1-comment',
        userId: 'charlie',
        createdAt: '2026-09-10T10:00:00.000Z',
        body: createCommentValue(
          'Comments are a great way to provide feedback and discuss changes.'
        ),
      },
      {
        id: 'discussion1-reply',
        userId: 'bob',
        createdAt: '2026-09-10T10:02:00.000Z',
        body: createCommentValue(
          'Agreed! The link to the docs makes it easy to learn more.'
        ),
      },
    ],
  },
  {
    id: 'discussion2',
    createdAt: '2026-09-10T10:05:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'overlapping',
    userId: 'bob',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 2], offset: trailingText.indexOf('overlapping') },
        focus: {
          path: [1, 2],
          offset: trailingText.indexOf('overlapping') + 'overlapping'.length,
        },
      },
    },
    messages: [
      {
        id: 'discussion2-comment',
        userId: 'bob',
        createdAt: '2026-09-10T10:05:00.000Z',
        body: createCommentValue(
          'Nice demonstration of overlapping annotations with both comments and suggestions!'
        ),
      },
      {
        id: 'discussion2-reply',
        userId: 'charlie',
        createdAt: '2026-09-10T10:07:00.000Z',
        body: createCommentValue(
          'This helps users understand how powerful the editor can be.'
        ),
      },
    ],
  },
];
